NULL,
4,
'{"men": {"brands": ["Zegna", "Tom Ford", "IWC", "Berluti"], "outfit": {"top": "Light grey or cream sport coat, white or pale blue shirt, no tie", "bottom": "Dark navy or charcoal trousers, slim cut", "shoes": "Berluti or Edward Green in cognac or tan", "bag": "Nothing, or a very slim leather card holder", "accessories": "IWC Portugieser or Cartier Santos, no other jewelry, perhaps a pocket square in crystal blue to acknowledge where you are"}, "color_palette": "Crystal clear, silver-grey, cream — the palette of someone who appreciates things that refract light", "budget_dupe": "A clean fitted blazer in light grey from Theory or COS. The crystal does the heavy lifting in this room — you just need to not clash with it."}, "women": {"brands": ["Celine", "Saint Laurent", "Messika", "Aquazzura"], "outfit": {"top": "A slip dress in champagne or silver, or a structured blazer over wide-leg silk trousers", "bottom": "High-waisted silk trousers in ivory or pale grey", "shoes": "Strappy heeled sandal in metallic or nude", "bag": "Celine clutch or small Saint Laurent Lou in silver", "accessories": "Messika diamond ear cuffs, thin silver or gold chain, understated is the only mode"}, "color_palette": "Champagne, silver, crystal white — someone who is not trying to compete with 4,500 pieces of Baccarat crystal (you will lose)", "budget_dupe": "A silk or satin slip dress from & Other Stories in champagne. Simple metallic accessories. The room will elevate you further than your budget can."}}',
true),

-- 5. Aman New York
('11111111-0000-0000-0000-000000000001',
'Aman New York',
'Midtown',
'Hotel Lobby',
'Aman took the top six floors of the Crown Building — one of the most significant Beaux Arts structures on Fifth Avenue — and turned it into the most expensive hotel in the city with barely a whisper. The aesthetic is stripped-down grandeur: marble floors, wood paneling, almost no signage. The bar and restaurant are members-club adjacent. If you have to ask what things cost here, you are still the target demographic but might want to sit down first.',
40.7618000, -73.9753000,
NULL,
5,
'{"men": {"brands": ["Loro Piana", "Brunello Cucinelli", "Rolex", "Berluti"], "outfit": {"top": "Cashmere crewneck in mushroom or stone, or a fine linen shirt in off-white — no tie, no blazer required", "bottom": "Stone or camel straight-leg trousers, impeccably pressed", "shoes": "Clean unbranded loafers in suede or minimal leather sneakers (Loro Piana or Common Projects)", "bag": "Nothing, or a very quiet leather portfolio", "accessories": "Rolex Datejust or Day-Date if you have it — the only acceptable ostentation here"}, "color_palette": "Stone, mushroom, camel, off-white — the palette of someone who finds conspicuous consumption gauche", "budget_dupe": "Uniqlo cashmere in a muted neutral, COS trousers in stone. Aman''s entire philosophy is about removing visual noise. Your wallet size is less important than your ability to be quiet about it."}, "women": {"brands": ["The Row", "Loro Piana", "Cartier", "Bottega Veneta"], "outfit": {"top": "Long-sleeve The Row cashmere in stone or cream, or a loose linen tunic", "bottom": "Wide-leg trousers in oatmeal or pale sand", "shoes": "Clean leather loafers or minimal slides", "bag": "Bottega Veneta Cassette in camel or cloud grey", "accessories": "Cartier Love bracelet, simple gold studs, nothing louder than a whisper"}, "color_palette": "Oatmeal, sand, camel, pale stone — the palette of someone who owns property in multiple time zones and never mentions it", "budget_dupe": "Toteme or COS for the neutrals. One really good bag borrowed or secondhand. Aman''s clientele has impeccable taste and zero desire to show off — match the energy, not the price tag."}}',
